{
  "id": "V036",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "청구서 검토 부담을 줄이고 의심 과다 청구를 검토하려는 목적이 보존됩니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "항목별 요율 비교, 의심 부분 파악, 근거 기록 및 담당자 확인 후 처리가 포함됩니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "화물 청구서의 항목과 합의된 요율을 대상으로 합니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "청구 항목별 금액과 합의 요율이 보존됩니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "과다 청구 의심 부분과 비교 근거를 검토 목록에 남기는 내용이 보존됩니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "담당자가 확인한 뒤 처리하며 자동 수정이나 대금 지급은 하지 않는다는 조건이 보존됩니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "세 관점에 원문에 없는 기능이 추가되지 않았습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "운송비 검토 담당자의 비교·확인 역할이 보존됩니다."
    }
  ],
  "issues": [],
  "permission_interpretation": "자동 수정이나 대금 지급은 금지되며, 담당자가 확인한 뒤 처리합니다. 담당자가 매번 직접 수정 또는 지급해야 한다고 단정하지 않습니다."
}
